// ==========================================
// 1. DATA ANALYSEREN & PARSEN
// ==========================================
let data;

if (typeof msg.payload === "object" && msg.payload !== null) {
    data = msg.payload;
} else {
    try {
        let rawText = msg.payload.toString().trim();
        data = JSON.parse(rawText);
    } catch (e) {
        node.error("Payload is geen geldige JSON: " + e.message);
        return null;
    }
}

// ==========================================
// 2. METADATA EXTRAHEREN (Sensor ID)
// ==========================================
let topicParts = msg.topic.split('/');
let sensorID = topicParts[topicParts.length - 1]; // Dit is "sensor_1" of "sensor_2"

// ==========================================
// 3. DYNAMISCHE FIELDS AANMAKEN
// ==========================================
if (data.hasOwnProperty('temperatuur')) {

    // We maken een leeg object voor de fields
    let dynamicFields = {};

    // We bouwen de veldnamen op: bijv. "temperatuur_sensor_1"
    dynamicFields["temperatuur_" + sensorID] = data.temperatuur;
    dynamicFields["luchtvochtigheid_" + sensorID] = data.luchtvochtigheid;
    dynamicFields["co2_" + sensorID] = data.co2;

    msg.payload = dynamicFields;

    // We behouden de tag voor de zekerheid (best practice)
    msg.tags = {
        device: sensorID
    };

    msg.measurement = "BevDecSensors";

    return msg;
} else {
    node.warn("Meting genegeerd: ontbrekende velden.");
    return null;
}
